// MARK: - helpers

func unhex(_ s: String) -> Data {
    var d = Data(); var i = s.startIndex
    while i < s.endIndex { let j = s.index(i, offsetBy: 2); d.append(UInt8(s[i..<j], radix: 16)!); i = j }
    return d
}
func hexs(_ d: Data) -> String { d.map { String(format: "%02x", $0) }.joined() }
func waitUntil(_ timeout: TimeInterval = 5, _ cond: () -> Bool) -> Bool {
    let end = Date().addingTimeInterval(timeout)
    while Date() < end { if cond() { return true }; Thread.sleep(forTimeInterval: 0.02) }
    return cond()
}
/// 确定性的伪随机切块
struct LCG { var s: UInt64; mutating func next(_ n: Int) -> Int { s = s &* 6364136223846793005 &+ 1442695040888963407; return Int((s >> 33) % UInt64(n)) } }
func chunks(_ d: Data, seed: UInt64, maxChunk: Int) -> [Data] {
    var g = LCG(s: seed); var out: [Data] = []; var i = 0
    while i < d.count { let n = min(d.count - i, 1 + g.next(maxChunk)); out.append(d.subdata(in: i..<i + n)); i += n }
    return out
}
func canon(_ d: Data) -> String { BPlist.canonical(try! BPlist.decode(d)) }
/// HomePlay 故意不宣告 Opus 输出（解码器未接），比较 MacPlay 夹具时先把该位去掉。
/// 用 NSDictionary 比较内容，不比较 bplist 的键顺序。
func infoMatchesIgnoringOutputOpus(_ a: Data, _ b: Data) -> Bool {
    func normalized(_ d: Data) -> NSDictionary {
        var x = try! BPlist.decodeDict(d)
        if var fs = x["audioFormats"] as? [[String: Any]] {
            for i in fs.indices {
                if let v = fs[i]["audioOutputFormats"] as? Int { fs[i]["audioOutputFormats"] = v & ~0x70000000 }
            }
            x["audioFormats"] = fs
        }
        return NSDictionary(dictionary: x)
    }
    return normalized(a).isEqual(normalized(b))
}

/// 测试用的事件通道加密：[u16 LE 长度][每字节 xor 0x5a]。形状同 ControlCipher（整帧才能解，尾巴留着）。
final class XorSealer: MessageSealer {
    func seal(_ plain: Data) throws -> Data {
        var d = Data([UInt8(plain.count & 0xff), UInt8(plain.count >> 8)]); d.append(contentsOf: plain.map { $0 ^ 0x5a }); return d
    }
    func open(_ buf: Data) throws -> (plain: Data, rest: Data) {
        var out = Data(), off = 0; let b = [UInt8](buf)
        while b.count - off >= 2 {
            let n = Int(b[off]) | Int(b[off + 1]) << 8
            guard b.count - off - 2 >= n else { break }
            out.append(contentsOf: b[off + 2..<off + 2 + n].map { $0 ^ 0x5a }); off += 2 + n
        }
        return (out, Data(b[off...]))
    }
}

func runTransportSuites() {
    // MARK: RTSP
    suite("transport-rtsp") {
        let pip = unhex(fx_rtspPipelined)
        func summary(_ ms: [RTSPMessage]) -> String {
            ms.map { [$0.method, $0.path, $0.proto, $0.cseq ?? "", String(decoding: $0.body, as: UTF8.self)].joined(separator: "|") }.joined(separator: ";")
        }
        let expected = fx_rtspPipelinedSummary.components(separatedBy: "|rest=")
        var whole = RTSPParser()
        expect(summary(whole.feed(pip)) == expected[0] && whole.pendingBytes == Int(expected[1]), "pipelined buffer in one piece matches MacPlay parseMessages")
        var allOK = true
        for seed in 1...40 {
            var p = RTSPParser(); var got: [RTSPMessage] = []
            for c in chunks(pip, seed: UInt64(seed), maxChunk: seed % 5 == 0 ? 2 : 17) { got += p.feed(c) }
            if summary(got) != expected[0] || p.pendingBytes != Int(expected[1]) { allOK = false }
        }
        expect(allOK, "40 random chunkings (incl. 1-2 byte reads) give identical messages")
        var one = RTSPParser(); var bytewise: [RTSPMessage] = []
        for b in pip { bytewise += one.feed(Data([b])) }
        expect(summary(bytewise) == expected[0], "byte-at-a-time feed")
        let ms = whole.feed(Data("b".utf8))   // 补齐最后一条正文 (content-length 3，已有 "ab")
        expect(ms.count == 1 && ms[0].method == "SETUP" && String(decoding: ms[0].body, as: UTF8.self) == "abb", "partial body completes on next feed")
        var p2 = RTSPParser()
        let r = p2.feed(unhex(fx_rtspPipelined)).first(where: { $0.isResponse })
        expect(r?.statusCode == 200, "event-channel response parses as isResponse/statusCode 200")

        let req = RTSPMessage(method: "POST", path: "/command", headers: ["cseq": "7"])
        let resp = rtspSerialize(RTSPResponse.plist(Data("abc".utf8)), for: req)
        expect(hexs(resp) == fx_rtspResp, "response serialization == MacPlay buildResponse (CSeq echo, Content-Length)")
        let r404 = rtspSerialize(RTSPResponse(status: 404), for: RTSPMessage(method: "GET", path: "/", proto: "HTTP/1.1", headers: ["cseq": "7"]))
        expect(hexs(r404) == fx_rtspResp404, "404 response echoes request protocol")
        let cmd = rtspEventCommand(body: Data("xy".utf8), cseq: 3)
        expect(String(decoding: cmd, as: UTF8.self) == "POST /command RTSP/1.0\r\nContent-Type: application/x-apple-binary-plist\r\nContent-Length: 2\r\nCSeq: 3\r\n\r\nxy", "event command framing")
    }

    // MARK: HID
    suite("transport-hid") {
        expect(hexs(HID.touchDescriptor(xMax: 1920, yMax: 720)) == fx_touchDesc1920x720, "touch descriptor 1920x720 == MacPlay")
        expect(hexs(HID.touchDescriptor(xMax: 800, yMax: 480)) == fx_touchDesc800x480, "touch descriptor 800x480 == MacPlay")
        expect(hexs(HID.knobDescriptor) == fx_knobDesc, "knob descriptor")
        expect(hexs(HID.mediaDescriptor) == fx_mediaDesc, "media descriptor")
        expect(hexs(HID.telephonyDescriptor) == fx_telephonyDesc, "telephony descriptor")
        expect(hexs(HID.touchReport([HIDContact(id: 0, x: 960.4, y: 359.5, down: true)])) == fx_touchRep1, "touchReport one contact (rounding .5 up)")
        expect(hexs(HID.touchReport([HIDContact(id: 0, x: 0, y: 0, down: true), HIDContact(id: 1, x: 1919, y: 719.49, down: true)])) == fx_touchRep2, "touchReport two contacts")
        expect(hexs(HID.touchReport([HIDContact(id: 0, x: 100.5, y: 200, down: false), HIDContact(id: 1, x: -5, y: 300, down: true)])) == fx_touchRep3, "touchReport up + negative clamp")
        expect(hexs(HID.touchReport([])) == fx_touchRepNone, "touchReport empty keeps slot indexes")
        expect(hexs(HID.touchReport(normalized: [(0, 0.25, 0.75, true)], streamWidth: 1920, streamHeight: 720)) == fx_touchRepNorm, "normalized 0..1 → stream pixels")
        expect(hexs(HID.knobReport(KnobState(select: true))) == fx_knobSelect, "knob select")
        expect(hexs(HID.knobReport(KnobState(select: true, home: true, back: true, x: 5, y: -300, wheel: 127))) == fx_knobAll, "knob all buttons + axis clamp")
        expect(hexs(HID.knobReport(KnobState(y: -127, wheel: -3))) == fx_knobRel, "knob negative axes")
        expect(hexs(HID.knobReport(KnobState())) == fx_knobZero, "knob release")
        expect(hexs(HID.mediaReport(HID.MediaButton.next.rawValue)) == fx_media4, "media next")
        expect(hexs(HID.telephonyReport(HID.TelephonyButton.pound.rawValue)) == fx_tel16, "telephony pound")
    }

    // MARK: bplist
    suite("transport-bplist") {
        func mainCfg() -> DisplayConfig {
            DisplayConfig(widthPixels: 1920, heightPixels: 720, widthPhysicalMm: 260, heightPhysicalMm: 98, fps: 60,
                          viewArea: DisplayInsets(top: 0, bottom: 0, left: 120, right: 0),
                          safeArea: DisplayInsets(top: 10, bottom: 20, left: 130, right: 5),
                          safeAreaDrawOutside: true, initialURL: "x-example://home")
        }
        var a = InfoConfig(sourceVersion: "950.7.1", deviceID: "AA:BB:CC:DD:EE:FF", bluetoothMAC: "11:22:33:44:55:66", name: "HomePlay Test", main: mainCfg())
        a.rightHandDrive = true; a.oemLabel = "Home"
        a.icons = [OEMIcon(widthPixels: 2, heightPixels: 2, data: unhex("89504e470d0a1a0a"))]
        let infoA = try! CarPlayPlist.infoResponse(a)
        expect(infoMatchesIgnoringOutputOpus(infoA, unhex(fx_infoA)),
               "/info (main+viewArea+safeArea+icon) equal to MacPlay's except intentional Opus-output omission")
        var b = InfoConfig(sourceVersion: "950.7.1", deviceID: "00:11:22:33:44:55", bluetoothMAC: "66:55:44:33:22:11", name: "Café ☕", main: DisplayConfig(widthPixels: 800, heightPixels: 480))
        b.hevc = true; b.disableAudioOutput = true; b.entertainmentSampleRate = 48000
        b.cluster = DisplayConfig(widthPixels: 480, heightPixels: 270, fps: 30, initialURL: "x://c")
        expect(canon(try! CarPlayPlist.infoResponse(b)) == canon(unhex(fx_infoB)), "/info (cluster, hevc, no audio, unicode name) equal to MacPlay's")
        var c = a; c.entertainmentSampleRate = 48000
        let ci = try! BPlist.decodeDict(try! CarPlayPlist.infoResponse(c))
        let formats = ci["audioFormats"] as? [[String: Any]]
        expect(formats?.count == 9 && (formats?.last?["audioOutputFormats"] as? Int) == 0x800000, "48 kHz picks AAC-LC 48k bit")
        let opusDeclared = formats?.contains { ((($0["audioOutputFormats"] as? Int) ?? 0) & 0x70000000) != 0 } ?? false
        // iPhone 只有在低延迟流里看到 Opus 时才会建无线音频流（真机 2026-10-20：只声明 PCM/AAC
        // 时连娱乐流 102 都不发）。解码器未接，所以真正收到 Opus 时必须标记不可播、不出声。
        expect(opusDeclared, "Opus advertised so the phone opens wireless audio")
        let (opus48, opus48Playable) = audioCodec(fromFormat: 0x40000000)
        expect(opus48Playable && opus48.isOpus && opus48.rate == 48000, "Opus 48k decodable (CoreAudio)")
        expect(BPlist.canonical(try! BPlist.decode(infoA)) == BPlist.canonical(try! BPlist.decode(try! BPlist.encode(try! BPlist.decode(infoA)))), "info plist round-trips")

        let touch = HID.touchReport([HIDContact(id: 0, x: 10, y: 20, down: true)])
        expect(canon(try! CarPlayPlist.hidSendReport(uuid: HID.touchUID, report: touch)) == canon(unhex(fx_hidSend)), "hidSendReport equal to MacPlay's")
        expect(canon(try! CarPlayPlist.forceKeyFrame()) == canon(unhex(fx_forceKey)), "forceKeyFrame equal to MacPlay's")
        expect(canon(try! CarPlayPlist.setupSessionResponse(timingPort: 49152, eventPort: 49153, keepAlivePort: 49154)) == canon(unhex(fx_setupSession)), "session SETUP response (with keepAlive) equal")
        expect(canon(try! CarPlayPlist.setupSessionResponse(timingPort: 50000, eventPort: 50001, hevc: true, altScreen: true)) == canon(unhex(fx_setupSessionHevcAlt)), "session SETUP response (hevc+alt, no keepAlive) equal")
        expect(canon(try! CarPlayPlist.setupStreamsResponse([(110, 40001), (111, 40002)])) == canon(unhex(fx_setupStreams)), "stream SETUP response equal")
        let d = try! BPlist.decodeDict(try! CarPlayPlist.hidSendReport(uuid: HID.knobUID, report: Data([1, 2, 3, 4])))
        expect(d["uuid"] as? String == "2a2a2a2b" && d["hidReport"] as? Data == Data([1, 2, 3, 4]) && d["type"] as? String == "hidSendReport", "hidSendReport round-trip")
        let big = try! BPlist.decodeDict(try! BPlist.encode(["n": 0x615653aee2, "f": 1.5, "t": true, "s": "é", "a": [1, "x"]] as [String: Any]))
        expect(BPlist.canonical(big) == #"{a:[i1,"x"],f:r1.5,n:i418060152546,s:"é",t:true}"#, "generic types round-trip")
    }

    // MARK: ScreenStream parser
    suite("transport-screen-parser") {
        let key = unhex(fx_screenKey), stream = unhex(fx_screenStream)
        let plain = [fx_screenPlain1, fx_screenPlain2, fx_screenPlain3].map(unhex)
        var okAll = true
        for seed in 1...30 {
            let p = try! ScreenStreamParser(key: key); var got: [ScreenMessage] = []
            for c in chunks(stream, seed: UInt64(seed), maxChunk: seed % 6 == 0 ? 3 : 700) { got += try! p.feed(c) }
            let want: [ScreenMessage] = [.config(codec: .h264, record: unhex(fx_screenAvcC)),
                .frame(nals: plain[0], keyframe: true), .frame(nals: plain[1], keyframe: false), .frame(nals: plain[2], keyframe: false)]
            if got != want || p.counter != 3 { okAll = false }
        }
        expect(okAll, "30 random chunkings: config + 3 decrypted frames, keyframe flags, counter == 3")
        let p = try! ScreenStreamParser(key: key)
        var bad = stream; bad[bad.count - 40] ^= 1   // 第 3 帧密文里翻一位
        let msgs = try! p.feed(bad)
        expect(msgs.count == 4 && msgs[3] == .frameRejected && p.counter == 2, "tampered frame rejected, counter does not advance")
        let p2 = try! ScreenStreamParser(key: key)
        var huge = Data(count: 128); huge[0] = 0x01; huge[1] = 0x00; huge[2] = 0x80; huge[3] = 0x00   // 0x00800001 > 8 MB
        var threw = false
        do { _ = try p2.feed(huge) } catch { threw = true }
        expect(threw, "body over 8 MB throws")
        expect((try? ScreenStreamParser(key: Data(count: 16))) == nil, "key must be 32 bytes")
        let (codec, rec) = ScreenStreamParser.codecData(fromConfig: unhex(fx_configBoxed))
        expect("\(codec)" == fx_configBoxedCodec && hexs(rec) == fx_configBoxedRecord, "avcC inside a box == MacPlay configToCodecData")
        let (c2, r2) = ScreenStreamParser.codecData(fromConfig: unhex(fx_screenAvcC))
        expect(c2 == .h264 && hexs(r2) == fx_screenAvcC, "bare avcC detected as h264")
        let nals = ScreenStreamParser.avcCToNALs(unhex(fx_screenAvcC))!
        expect(nals.count > 8 && nals[4] & 0x1f == 7, "avcC → length-prefixed SPS,PPS")
    }

    // MARK: iAP 隧道（流 130）解析：帧层与 ControlCipher 同形、nonce 与屏幕流同形、APTransportPackage 32B 头
    suite("transport-iap-tunnel-parser") {
        let key = unhex(fx_screenKey)
        let plain = [fx_screenPlain1, fx_screenPlain2, fx_screenPlain3].map(unhex)
        // nonce：4 零字节 + 8 字节小端计数——与 ScreenStreamParser.nonce 逐字节一致
        var nonceOK = true
        for n: UInt64 in [0, 1, 7, 1007, 0x1_0000_0001] {
            let a: [UInt8] = PairingCrypto.nonce64(n)
            let b: [UInt8] = [UInt8](ScreenStreamParser.nonce(counter: n))
            if a != b { nonceOK = false }
        }
        expect(nonceOK, "tunnel nonce == ScreenStreamParser.nonce (4 zero + 8 LE)")
        // 明文流：3 个 'comm' 包夹一个别的类型（应被忽略但不打断解析）
        var other = APTransportPackage.comm(Data([9, 9, 9])); other[16] = 0x74; other[17] = 0x65; other[18] = 0x73; other[19] = 0x74   // 'test'
        let stream = APTransportPackage.comm(plain[0]) + other + APTransportPackage.comm(plain[1]) + APTransportPackage.comm(plain[2])
        // 帧层用 ControlCipher 的写方向封（>16 KiB 自动拆帧）：解析器必须能解它
        let sealed = Data(try! ControlCipher(readKey: [UInt8](key), writeKey: [UInt8](key)).encrypt([UInt8](stream)))
        let frames = (stream.count + ControlCipher.maxPayload - 1) / ControlCipher.maxPayload
        var okAll = true
        for seed in 1...30 {
            let p = try! IapTunnelParser(key: key); var got: [APTransportPackage] = []
            for c in chunks(sealed, seed: UInt64(seed), maxChunk: seed % 6 == 0 ? 3 : 700) { got += try! p.feed(c) }
            let bodies = got.filter(\.isIap).map(\.body)
            if bodies != plain || got.count != 4 || got[1].isIap || Int(p.counter) != frames { okAll = false }
        }
        expect(okAll, "30 random chunkings: 3 iAP bodies out, 'test' package ignored, counter == \(frames) frames")
        let single = try! IapTunnelParser(key: key)
        let got = try! single.feed(sealed)
        expect(got.first?.size == UInt32(32 + plain[0].count) && got.first?.messageType == APTransportPackage.messageTypeComm, "header: size@0 BE, 'comm'@16")
        var bad = sealed; bad[bad.count - 40] ^= 1
        let tampered = try! IapTunnelParser(key: key)
        var threw = false
        do { _ = try tampered.feed(bad) } catch { threw = true }
        expect(threw, "tampered frame → throws (connection must drop)")
        let bogus = try! IapTunnelParser(key: key)
        let tiny = Data(try! ControlCipher(readKey: [UInt8](key), writeKey: [UInt8](key)).encrypt([0, 0, 0, 8] + [UInt8](repeating: 0, count: 28)))
        var threwSize = false
        do { _ = try bogus.feed(tiny) } catch IapTunnelError.implausiblePackage(let n) { threwSize = n == 8 } catch {}
        expect(threwSize, "package size < 32 → implausiblePackage")
        expect((try? IapTunnelParser(key: Data(count: 16))) == nil, "key must be 32 bytes")
    }

    // MARK: ScreenStream → H264Sink
    suite("transport-screen-adapter") {
        let ws = try! WSServer(port: 0)
        let sink = H264Sink(server: ws)
        let adapter = ScreenStreamH264Adapter(sink: sink)
        let p = try! ScreenStreamParser(key: unhex(fx_screenKey))
        for m in try! p.feed(unhex(fx_screenStream)) {
            switch m {
            case .config(let c, let r): adapter.handleConfig(codec: c, record: r)
            case .frame(let n, _): adapter.handleFrame(n)
            case .frameRejected: break
            }
        }
        expect(sink.lastConfig != nil, "sink received VIDEO_CONFIG from avcC")
        expect(sink.frames == 3, "sink emitted 3 frames (frames=\(sink.frames))")

        // 真 socket 走一遍
        let ws2 = try! WSServer(port: 0)
        let sink2 = H264Sink(server: ws2), ad2 = ScreenStreamH264Adapter(sink: sink2)
        let screen = ScreenStream(key: unhex(fx_screenKey))
        ad2.attach(to: screen)
        let port = try! screen.start()
        expect(port > 0, "ScreenStream listens on ephemeral port \(port)")
        let q = DispatchQueue(label: "t.client")
        let c = NWConnection(host: "127.0.0.1", port: NWEndpoint.Port(rawValue: port)!, using: .tcp)
        c.start(queue: q)
        for part in chunks(unhex(fx_screenStream), seed: 9, maxChunk: 300) { c.send(content: part, completion: .contentProcessed { _ in }) }
        expect(waitUntil { sink2.frames == 3 }, "TCP path: config + 3 frames reach the sink (frames=\(sink2.frames))")
        expect(sink2.lastConfig != nil, "TCP path: VIDEO_CONFIG built")
        c.cancel(); screen.stop()
    }

    // MARK: 事件通道
    suite("transport-event-channel") {
        let sealer = XorSealer()
        let ch = EventChannel(sealer: { XorSealer() })
        var requests: [RTSPMessage] = []
        let port = try! ch.start()
        ch.onRequest = { requests.append($0) }
        let q = DispatchQueue(label: "t.evclient")
        let c = NWConnection(host: "127.0.0.1", port: NWEndpoint.Port(rawValue: port)!, using: .tcp)
        let rx = LockedData()
        c.start(queue: q)
        func loop() { c.receive(minimumIncompleteLength: 1, maximumLength: 65536) { d, _, _, e in if let d { rx.append(d) }; if e == nil { loop() } } }
        loop()
        expect(waitUntil { ch.isConnected }, "phone connects to event port")
        ch.sendTouches([(0, 0.5, 0.5, true)], streamWidth: 800, streamHeight: 480)
        ch.sendKnob(KnobState(home: true))
        ch.forceKeyFrame()
        expect(waitUntil { var t = RTSPParser(); return t.feed((try? sealer.open(rx.get()))?.plain ?? Data()).count == 4 }, "4 commands arrive sealed")
        var parser = RTSPParser()
        let cmds = parser.feed((try! sealer.open(rx.get())).plain)
        expect(cmds.map { $0.cseq ?? "" } == ["1", "2", "3", "4"] && cmds.allSatisfy { $0.method == "POST" && $0.path == "/command" && $0.headers["content-type"] == plistContentType }, "CSeq increments, POST /command, plist content type")
        let touch = try! BPlist.decodeDict(cmds[0].body)
        expect(touch["type"] as? String == "hidSendReport" && touch["uuid"] as? String == "2a2a2a2a"
               && touch["hidReport"] as? Data == HID.touchReport(normalized: [(0, 0.5, 0.5, true)], streamWidth: 800, streamHeight: 480), "touch command carries the 400,240 report")
        let knob = try! BPlist.decodeDict(cmds[1].body), rel = try! BPlist.decodeDict(cmds[2].body)
        expect(knob["hidReport"] as? Data == Data([2, 0, 0, 0]) && rel["hidReport"] as? Data == Data([0, 0, 0, 0]), "momentary knob = pressed then released")
        expect(canon(cmds[3].body) == canon(unhex(fx_forceKey)), "forceKeyFrame command body")

        rx.clear()
        let phoneReq = "POST /feedback RTSP/1.0\r\nCSeq: 42\r\nContent-Length: 0\r\n\r\n"
        c.send(content: try! sealer.seal(Data(phoneReq.utf8)), completion: .contentProcessed { _ in })
        expect(waitUntil { !rx.get().isEmpty }, "phone request gets an answer")
        var p2 = RTSPParser()
        let ans = p2.feed((try! sealer.open(rx.get())).plain)
        expect(ans.count == 1 && ans[0].statusCode == 200 && ans[0].cseq == "42", "answer is 200 with CSeq echoed")
        expect(requests.count == 1 && requests[0].path == "/feedback", "onRequest saw the phone request")
        c.cancel(); ch.stop()
    }

    // MARK: 时钟同步口 / keep-alive
    suite("transport-timing") {
        let t = TimingServer()
        let port = try! t.listen()
        expect(port > 0, "timing UDP port bound (\(port))")
        let c = NWConnection(host: "127.0.0.1", port: NWEndpoint.Port(rawValue: port)!, using: .udp)
        let q = DispatchQueue(label: "t.udp")
        let got = LockedData()
        c.start(queue: q)
        var req = Data(count: 32); req[0] = 0x80; req[1] = 210; req[3] = 7
        for i in 0..<8 { req[24 + i] = UInt8(0xa0 + i) }
        c.send(content: req, completion: .contentProcessed { _ in })
        c.receiveMessage { d, _, _, _ in if let d { got.append(d) } }
        expect(waitUntil { got.get().count == 32 }, "phone-initiated sync request is answered")
        let r = got.get()
        expect(r.count == 32 && r[1] == 211 && Array(r[8..<16]) == (0..<8).map { UInt8(0xa0 + $0) }, "response type 211 echoes originate")
        let ntp = NTP.ntp64Now()
        expect(ntp >> 32 > 3_900_000_000, "NTP seconds are in the 1900-epoch domain")
        t.stop(); c.cancel()
        let k = KeepAliveServer(peerHost: "127.0.0.1")
        expect((try? k.listen()) ?? 0 > 0, "keep-alive UDP port bound"); k.stop()
    }

    // MARK: Discovery
    suite("transport-discovery") {
        let name = "HomePlayTest-\(Int.random(in: 10000...99999))"
        let txt = DiscoveryTXT(deviceid: "AA:BB:CC:DD:EE:FF", pi: "11111111-2222-3333-4444-555555555555", pk: String(repeating: "ab", count: 32))
        let d = Discovery(serviceName: name, txt: txt)
        guard let port = try? d.start() else { expect(false, "advertise starts"); return }
        expect(port > 0, "advertising on port \(port)")
        // 控制口必须能接 IPv6；IPv6 备用地址重试靠它
        let got6 = LockedBox<Bool>(false)
        let d6 = Discovery(serviceName: "HomePlayV6-\(Int.random(in: 10000...99999))", txt: txt)
        if let port6 = try? d6.start(port: 0, onConnection: { c in got6.set(true); c.cancel() }) {
            let c6 = NWConnection(host: "::1", port: NWEndpoint.Port(rawValue: port6)!, using: .tcp)
            c6.start(queue: DispatchQueue(label: "t.ipv6"))
            expect(waitUntil(5) { got6.get() }, "control listener accepts IPv6 loopback")
            c6.cancel()
        } else { expect(false, "IPv6 control listener starts") }
        d6.stop()
        let browser = NWBrowser(for: .bonjourWithTXTRecord(type: "_airplay._tcp", domain: nil), using: .tcp)
        let found = LockedBox<[String: String]?>(nil)
        browser.browseResultsChangedHandler = { results, _ in
            for r in results {
                if case .service(let n, _, _, _) = r.endpoint, n == name, case .bonjour(let rec) = r.metadata {
                    found.set(rec.dictionary)
                }
            }
        }
        browser.start(queue: DispatchQueue(label: "t.browse"))
        let ok = waitUntil(5) { found.get() != nil }
        browser.cancel(); d.stop()
        if !ok { expect(false, "browse found \(name) within 5 s (local-network permission or mDNS may block)"); return }
        let rec = found.get()!
        for k in ["deviceid", "features", "flags", "model", "srcvers", "protovers", "pi", "pk"] {
            expect(rec[k] != nil, "TXT has \(k) = \(rec[k] ?? "-")")
        }
        expect(rec["features"] == "0x44540380,0x61" && rec["model"] == "MacPlay" && rec["srcvers"] == "950.7.1", "MacPlay default TXT values")
    }

    suite("ctrl-probe-schedule") {
        var s = CtrlProbeSchedule()
        expect(s.due("phone", now: 0) == 1, "first ctrl probe fires immediately")
        expect(s.due("phone", now: 4.9) == nil, "5 s spacing between ctrl probes")
        var got: [Int] = []
        for t in stride(from: 5.0, through: 30.0, by: 5.0) { if let n = s.due("phone", now: t) { got.append(n) } }
        expect(got == [2, 3, 4, 5, 6, 7], "attempts 2..7 at 5 s")
        expect(s.due("phone", now: 59.9) == nil, "after 7, slow 30 s window")
        expect(s.due("phone", now: 60) == 1, "slow window restarts at 1 instead of giving up forever")
    }
}

final class LockedData: @unchecked Sendable {
    private var d = Data(); private let l = NSLock()
    func append(_ x: Data) { l.lock(); d.append(x); l.unlock() }
    func get() -> Data { l.lock(); defer { l.unlock() }; return d }
    func clear() { l.lock(); d = Data(); l.unlock() }
}
final class LockedBox<T>: @unchecked Sendable {
    private var v: T; private let l = NSLock()
    init(_ v: T) { self.v = v }
    func get() -> T { l.lock(); defer { l.unlock() }; return v }
    func set(_ n: T) { l.lock(); v = n; l.unlock() }
}
